insert into public.fact_estimate(metric_code,reference_year,source_id,universe,geo_level,geo_code,segment_json,segment_key,estimate,unit,precision_flag,observed_or_modeled,method_id,version,source_page,source_url,note)
select r.m, r.y, s.id, uu.t, r.gl, r.gc, r.sj::jsonb,
  coalesce((select string_agg(k||'='||v,'|' order by k) from jsonb_each_text(r.sj::jsonb) e(k,v)),''),
  r.e, r.un, 'pending_microdata_recalculation','observed',
  (select id from public.dim_method where method_code='official_published_aggregate'),
  '2026-10-13', r.p, s.official_url, nn.t
from allrows r
join public.source_document s on s.source_code = case when r.m like 'vabcoel%' then 'vabcoel_2024' else 'endutih_2025_presentation' end
join uu on uu.k = r.u
left join nn on nn.k = r.n;

insert into public.dim_segment(segment_code,dimension,value,label)
select distinct lower(regexp_replace(k||'_'||v,'[^a-zA-Z0-9]+','_','g')), k, v, v
from public.fact_estimate, jsonb_each_text(segment_json) e(k,v)
on conflict do nothing;

insert into public.fact_barrier(fact_estimate_id, barrier_code, barrier_label, reference_year, source_id, universe, geo_level, geo_code, estimate, unit, precision_flag, observed_or_modeled, method_id, version)
select id, lower(regexp_replace(segment_json->>'nonbuyer_reason','[^a-zA-Z0-9]+','_','g')), segment_json->>'nonbuyer_reason', reference_year, source_id, universe, geo_level, geo_code, estimate, unit, precision_flag, observed_or_modeled, method_id, version
from public.fact_estimate where metric_code = 'nonbuyer_reason_pct_as_published';

insert into public.fact_category(fact_estimate_id, category_code, category_label, reference_year, source_id, universe, geo_level, geo_code, estimate, unit, precision_flag, observed_or_modeled, method_id, version, note)
select id, lower(regexp_replace(segment_json->>'purchase_category','[^a-zA-Z0-9]+','_','g')), segment_json->>'purchase_category', reference_year, source_id, universe, geo_level, geo_code, estimate, unit, precision_flag, observed_or_modeled, method_id, version, note
from public.fact_estimate where metric_code = 'online_purchase_category_pct';

insert into public.source_lineage(fact_table, fact_id, source_id, source_page, source_url, transformation, loaded_version)
select 'fact_estimate', id, source_id, source_page, source_url, 'Transcripción de agregado oficial publicado (sin recálculo)', version from public.fact_estimate;
insert into public.source_lineage(fact_table, fact_id, source_id, source_page, source_url, transformation, loaded_version)
select 'fact_barrier', b.id, b.source_id, f.source_page, f.source_url, 'Derivado 1:1 de fact_estimate', b.version from public.fact_barrier b join public.fact_estimate f on f.id = b.fact_estimate_id;
insert into public.source_lineage(fact_table, fact_id, source_id, source_page, source_url, transformation, loaded_version)
select 'fact_category', c.id, c.source_id, f.source_page, f.source_url, 'Derivado 1:1 de fact_estimate', c.version from public.fact_category c join public.fact_estimate f on f.id = c.fact_estimate_id;

insert into public.methodology_note(note_code, title, body, topic, source_id) values
 ('universe_household_vs_dwelling','Hogares (ENDUTIH) vs. viviendas (EIC)','El porcentaje de hogares con internet de ENDUTIH usa como universo el total de hogares. La disponibilidad de internet en la Encuesta Intercensal (EIC 2025) usa como universo las viviendas particulares habitadas. Son universos distintos: no deben compararse ni combinarse directamente.','universe',(select id from public.source_document where source_code='endutih_2025')),
 ('endutih_design','ENDUTIH: diseño muestral','Usar factores de expansión, estrato y UPM. La compra por internet es un resultado individual condicionado a personas usuarias de internet. Productos, barreras y problemas admiten respuestas múltiples: los porcentajes no se suman.','survey_design',(select id from public.source_document where source_code='endutih_2025')),
 ('enigh_income','ENIGH: ingreso imputado','No se une ENIGH con ENDUTIH a nivel individual. El ingreso se incorpora por imputación múltiple o statistical matching y se reporta como ingreso/decil imputado con su incertidumbre. La variable lugar_comp no equivale al gasto electrónico total.','imputation',(select id from public.source_document where source_code='enigh_2024')),
 ('eic_mrp','EIC 2025: MRP municipal','La EIC aporta denominadores y celdas demográficas municipales. La tasa de compra municipal se estima por MRP/postestratificación y se etiqueta como estimación modelada.','mrp',(select id from public.source_document where source_code='eic_2025')),
 ('enoe_files','ENOE: archivos y universos','Usar VIVT, HOGT, SDEMT, COE1T y COE2T del trimestre seleccionado, con factor trimestral, estrato, UPM y universos de población ocupada.','survey_design',(select id from public.source_document where source_code='enoe_2025')),
 ('vabcoel_scope','VABCOEL no es ventas','VABCOEL es valor agregado bruto del comercio electrónico. No equivale a ventas, GMV ni gasto de los hogares. Los efectos de escenarios se presentan como rangos bajo supuestos, no como pronósticos oficiales.','scope',(select id from public.source_document where source_code='vabcoel_2024')),
 ('precision_pending','Precisión pendiente','Las cifras actuales son agregados publicados. Error estándar, intervalos de confianza y CV se recalcularán con microdatos; mientras tanto se marcan como “precisión pendiente”.','precision',null),
 ('no_causality','Asociación no es causalidad','Las relaciones entre barreras, segmentos y compra digital son asociaciones observacionales; no implican causalidad.','interpretation',null);